   142→
   143→  if (!result.ok) {
   144→    switch (result.error) {
   145→      case "not_found":
   146→        error(errors.reference.specNotFound(ref));
   147→        break;
   148→      case "ambiguous":
   149→        error(errors.reference.ambiguous(ref));
   150→        for (const candidate of result.candidates) {
   151→          const item = items.find((i) => i._ulid === candidate);
   152→          const slug = item?.slugs[0] || "";
   153→          console.error(
   154→            `  - ${index.shortUlid(candidate)} ${slug ? `(${slug})` : ""}`,
   155→          );
   156→        }
   157→        break;
   158→      case "duplicate_slug":
   159→        error(errors.reference.slugMapsToMultiple(ref));
   160→        for (const candidate of result.candidates) {
   161→          console.error(`  - ${index.shortUlid(candidate)}`);
   162→        }
   163→        break;
   164→    }
   165→    process.exit(EXIT_CODES.NOT_FOUND);
   166→  }
   167→
   168→  // Check if it's actually a spec item (not a task)
   169→  const item = items.find((i) => i._ulid === result.ulid);
   170→  if (!item) {
   171→    // Check if it's a task
   172→    const task = tasks.find((t) => t._ulid === result.ulid);
   173→    if (task) {
