        });
      }

      await saveTask(ctx, newTask);
      result.createdTasks.push(`@${uniqueSlug}`);
      newPlan.derived_tasks.push(`@${uniqueSlug}`);

      info(`Derived task: @${uniqueSlug}`);
    }
  }

