211→    return {};
212→  }
213→
214→  const tasksContent = tasksMatch[1].trim();
215→
216→  // Check for derive_from_specs flag
217→  const deriveMatch = tasksContent.match(/^derive_from_specs:\s*(true|false)/m);
218→  const deriveFromSpecs = deriveMatch ? deriveMatch[1] === "true" : undefined;
219→
220→  // Extract YAML code block for additional tasks
221→  const yamlMatch = tasksContent.match(/```(?:yaml)?\s*\n([\s\S]*?)\n```/);
222→
223→  let additionalTasks: PlanTask[] | undefined;
224→
225→  if (yamlMatch) {
226→    const yamlContent = yamlMatch[1];
227→
228→    try {
229→      const parsed = parseYaml(yamlContent);
230→
231→      if (Array.isArray(parsed)) {
232→        additionalTasks = [];
233→        for (let i = 0; i < parsed.length; i++) {
234→          const result = PlanTaskSchema.safeParse(parsed[i]);
235→          if (!result.success) {
236→            errors.push({
237→              type: "validation",
238→              message: `Task at index ${i} validation failed: ${result.error.message}`,
239→            });
240→            continue;
241→          }
242→          additionalTasks.push(result.data);
243→        }
244→      }
245→    } catch (err) {
246→      errors.push({
247→        type: "yaml",
248→        message: `Malformed YAML in Tasks section: ${err instanceof Error ? err.message : String(err)}`,
249→      });
250→    }
251→  }
252→
253→  return {
254→    derive_from_specs: deriveFromSpecs,
255→    additional_tasks: additionalTasks,
256→  };
