259→/**
260→ * Extract ## Implementation Notes section.
261→ *
262→ * AC: @plan-import ac-13 - Extract implementation notes as plain text
263→ */
264→function extractImplementationNotes(content: string): string | null {
265→  const notesMatch = content.match(/##\s+Implementation\s+Notes\s*\n([\s\S]*?)(?=\n##\s+\w|$)/);
266→
267→  if (!notesMatch) {
268→    return null;
269→  }
270→
271→  return notesMatch[1].trim();
272→}
