675→
676→    // AC: @plan-import ac-15, ac-23 - Exit code 0 on success
677→    if (!options.dryRun && successCount > 0) {
678→      success(
679→        `\nImported plan: ${successCount} items created, ${errorCount} errors`,
680→      );
681→    }
682→  }  // end of else block (non-JSON output)
683→
684→  // Exit code logic
685→  // AC: @plan-import ac-15 - Dry run exits 0
686→  // AC: @plan-import ac-23 - Success with some errors still exits 0
687→  process.exit(EXIT_CODES.SUCCESS);
688→}
689→
690→/**
691→ * Generate URL-safe slug from title
692→ */
693→function generateSlug(title: string): string {
694→  return title
695→    .toLowerCase()
696→    .replace(/[^a-z0-9]+/g, "-")
697→    .replace(/^-|-$/g, "")
698→    .slice(0, 50);
699→}
