    60→ * Parsed plan document structure
    61→ */
    62→export interface ParsedPlanDocument {
    63→  title: string;
    64→  content: string;
    65→  specs: PlanSpec[];
    66→  tasks: TasksSection;
    67→  implementationNotes: string | null;
    68→  errors: ParseError[];
    69→}
    70→
    71→/**
    72→ * Parse error with context
    73→ */
    74→export interface ParseError {
    75→  type: "yaml" | "validation" | "dependency" | "circular";
    76→  message: string;
    77→  line?: number;
    78→  specIndex?: number;
    79→  spec?: PlanSpec;
    80→}
    81→
    82→/**
    83→ * Parse a plan document from markdown text.
    84→ *
    85→ * AC: @plan-import ac-11 - Extract and parse ## Specs YAML blocks
    86→ * AC: @plan-import ac-12 - Parse Tasks section for derive_from_specs
    87→ * AC: @plan-import ac-13 - Extract ## Implementation Notes section
    88→ * AC: @plan-import ac-21 - Report YAML parse errors with line numbers
    89→ */
    90→export function parsePlanDocument(content: string): ParsedPlanDocument {
    91→  const errors: ParseError[] = [];
    92→
    93→  // Extract title from first heading
    94→  const titleMatch = content.match(/^#\s+(.+)$/m);
    95→  const title = titleMatch ? titleMatch[1].trim() : "Untitled Plan";
    96→
    97→  // Extract ## Specs section
    98→  const specs = extractSpecsSection(content, errors);
    99→
   100→  // Extract ## Tasks section
   101→  const tasks = extractTasksSection(content, errors);
   102→
   103→  // Extract ## Implementation Notes section
   104→  const implementationNotes = extractImplementationNotes(content);
   105→
   106→  return {
   107→    title,
   108→    content,
   109→    specs,
   110→    tasks,
   111→    implementationNotes,
   112→    errors,
   113→  };
   114→}
   115→
   116→/**
   117→ * Extract and parse the ## Specs section.
   118→ *
   119→ * AC: @plan-import ac-11 - Parse YAML array of spec definitions
   120→ * AC: @plan-import ac-21 - Handle YAML parse errors
   121→ * AC: @plan-import ac-22 - Validate required fields
   122→ */
   123→function extractSpecsSection(content: string, errors: ParseError[]): PlanSpec[] {
   124→  // Find ## Specs section
   125→  const specsMatch = content.match(/##\s+Specs\s*\n([\s\S]*?)(?=\n##\s+\w|$)/);
   126→
   127→  if (!specsMatch) {
   128→    return [];
   129→  }
   130→
   131→  const specsContent = specsMatch[1];
   132→
   133→  // Extract YAML code block
   134→  const yamlMatch = specsContent.match(/```(?:yaml)?\s*\n([\s\S]*?)\n```/);
   135→
   136→  if (!yamlMatch) {
   137→    errors.push({
   138→      type: "validation",
   139→      message:
   140→        "Specs section found but contains no YAML code block. Wrap specs in ```yaml ... ```",
   141→    });
   142→    return [];
   143→  }
   144→
   145→  const yamlContent = yamlMatch[1];
   146→
   147→  // Parse YAML
   148→  let parsed: unknown;
   149→  try {
   150→    parsed = parseYaml(yamlContent);
   151→  } catch (err) {
   152→    errors.push({
   153→      type: "yaml",
   154→      message: `Malformed YAML in Specs section: ${err instanceof Error ? err.message : String(err)}`,
   155→    });
   156→    return [];
   157→  }
   158→
   159→  // Validate array
   160→  if (!Array.isArray(parsed)) {
   161→    errors.push({
   162→      type: "validation",
   163→      message: "Specs section must contain a YAML array",
   164→    });
   165→    return [];
   166→  }
   167→
   168→  // Validate each spec
   169→  const specs: PlanSpec[] = [];
   170→
   171→  for (let i = 0; i < parsed.length; i++) {
   172→    const spec = parsed[i];
   173→
   174→    // Validate required title field
   175→    if (!spec || typeof spec !== "object" || !("title" in spec)) {
   176→      errors.push({
   177→        type: "validation",
   178→        message: `Spec at index ${i} missing required field: title`,
   179→        specIndex: i,
   180→      });
   181→      continue;
   182→    }
   183→
   184→    // Validate against schema
   185→    const result = PlanSpecSchema.safeParse(spec);
   186→    if (!result.success) {
   187→      errors.push({
   188→        type: "validation",
   189→        message: `Spec at index ${i} validation failed: ${result.error.message}`,
   190→        specIndex: i,
   191→      });
   192→      continue;
   193→    }
   194→
   195→    specs.push(result.data);
   196→  }
   197→
   198→  return specs;
   199→}
   200→
   201→/**
   202→ * Extract and parse the ## Tasks section.
   203→ *
   204→ * AC: @plan-import ac-12 - Parse derive_from_specs flag
   205→ * AC: @plan-import ac-27 - Parse additional_tasks array
   206→ */
   207→function extractTasksSection(content: string, errors: ParseError[]): TasksSection {
   208→  // Find ## Tasks section
   209→  const tasksMatch = content.match(/##\s+Tasks\s*\n([\s\S]*?)(?=\n##\s+\w|$)/);
   210→
   211→  if (!tasksMatch) {
   212→    return {};
   213→  }
   214→
   215→  const tasksContent = tasksMatch[1].trim();
   216→
   217→  // Check for derive_from_specs flag
   218→  const deriveMatch = tasksContent.match(/^derive_from_specs:\s*(true|false)/m);
   219→  const deriveFromSpecs = deriveMatch ? deriveMatch[1] === "true" : undefined;
   220→
   221→  // Extract YAML code block for additional tasks
   222→  const yamlMatch = tasksContent.match(/```(?:yaml)?\s*\n([\s\S]*?)\n```/);
   223→
   224→  let additionalTasks: PlanTask[] | undefined;
   225→
   226→  if (yamlMatch) {
   227→    const yamlContent = yamlMatch[1];
   228→
   229→    try {
   230→      const parsed = parseYaml(yamlContent);
   231→
   232→      if (Array.isArray(parsed)) {
   233→        additionalTasks = [];
   234→        for (let i = 0; i < parsed.length; i++) {
   235→          const result = PlanTaskSchema.safeParse(parsed[i]);
   236→          if (!result.success) {
   237→            errors.push({
   238→              type: "validation",
   239→              message: `Task at index ${i} validation failed: ${result.error.message}`,
   240→            });
   241→            continue;
   242→          }
   243→          additionalTasks.push(result.data);
   244→        }
   245→      }
   246→    } catch (err) {
   247→      errors.push({
   248→        type: "yaml",
   249→        message: `Malformed YAML in Tasks section: ${err instanceof Error ? err.message : String(err)}`,
   250→      });
   251→    }
   252→  }
   253→
   254→  return {
   255→    derive_from_specs: deriveFromSpecs,
   256→    additional_tasks: additionalTasks,
   257→  };
   258→}
   259→
   260→/**
   261→ * Extract ## Implementation Notes section.
   262→ *
   263→ * AC: @plan-import ac-13 - Extract implementation notes as plain text
   264→ */
   265→function extractImplementationNotes(content: string): string | null {
   266→  const notesMatch = content.match(/##\s+Implementation\s+Notes\s*\n([\s\S]*?)(?=\n##\s+\w|$)/);
   267→
   268→  if (!notesMatch) {
   269→    return null;
   270→  }
   271→
   272→  return notesMatch[1].trim();
   273→}
   274→
   275→/**
   276→ * Sort specs in topological order (parents before children).
   277→ *
   278→ * AC: @plan-import ac-16 - Create specs in dependency order
   279→ * AC: @plan-import ac-18 - Detect circular dependencies
   280→ *
   281→ * @returns Sorted specs or null if circular dependency detected
   282→ */
   283→export function topologicalSort(
   284→  specs: PlanSpec[],
   285→): { sorted: PlanSpec[]; error: ParseError | null } {
   286→  // Build adjacency list
   287→  const graph = new Map<string, string[]>();
   288→  const specBySlug = new Map<string, PlanSpec>();
   289→
   290→  for (const spec of specs) {
   291→    const slug = spec.slug || slugify(spec.title);
   292→    if (specBySlug.has(slug)) {
   293→      return {
   294→        sorted: [],
   295→        error: {
   296→          type: "validation",
   297→          message: `Duplicate slug detected: "${slug}". Ensure each spec has a unique slug or title.`,
   298→        },
   299→      };
   300→    }
   301→    specBySlug.set(slug, spec);
   302→    graph.set(slug, []);
   303→  }
   304→
   305→  // Add edges for parent dependencies
   306→  for (const spec of specs) {
   307→    const slug = spec.slug || slugify(spec.title);
   308→    if (spec.parent) {
   309→      const parentRef = spec.parent.startsWith("@") ? spec.parent.slice(1) : spec.parent;
   310→
   311→      // Only add edge if parent is in this plan (local reference)
   312→      if (specBySlug.has(parentRef)) {
   313→        const children = graph.get(parentRef) || [];
   314→        children.push(slug);
   315→        graph.set(parentRef, children);
   316→      }
   317→    }
   318→  }
   319→
   320→  // Detect cycles using DFS
   321→  const visited = new Set<string>();
   322→  const recursionStack = new Set<string>();
   323→
   324→  function hasCycle(node: string, path: string[]): string[] | null {
   325→    visited.add(node);
   326→    recursionStack.add(node);
   327→
   328→    const children = graph.get(node) || [];
   329→    for (const child of children) {
   330→      if (!visited.has(child)) {
   331→        const cyclePath = hasCycle(child, [...path, child]);
   332→        if (cyclePath) return cyclePath;
   333→      } else if (recursionStack.has(child)) {
   334→        return [...path, child];
   335→      }
   336→    }
   337→
   338→    recursionStack.delete(node);
   339→    return null;
   340→  }
   341→
   342→  for (const slug of graph.keys()) {
   343→    if (!visited.has(slug)) {
   344→      const cyclePath = hasCycle(slug, [slug]);
   345→      if (cyclePath) {
   346→        const cycleRefs = cyclePath.map(s => `@${s}`).join(" -> ");
   347→        return {
   348→          sorted: [],
   349→          error: {
   350→            type: "circular",
   351→            message: `Circular parent reference: ${cycleRefs}`,
   352→          },
   353→        };
   354→      }
   355→    }
   356→  }
   357→
   358→  // Topological sort using DFS
   359→  const sorted: PlanSpec[] = [];
   360→  const processed = new Set<string>();
   361→
   362→  function visit(node: string) {
   363→    if (processed.has(node)) return;
   364→
   365→    const spec = specBySlug.get(node);
   366→    if (!spec) return;
   367→
   368→    // Visit parent first if it's in this plan
   369→    if (spec.parent) {
   370→      const parentRef = spec.parent.startsWith("@") ? spec.parent.slice(1) : spec.parent;
   371→      if (specBySlug.has(parentRef)) {
   372→        visit(parentRef);
   373→      }
   374→    }
   375→
   376→    processed.add(node);
   377→    sorted.push(spec);
   378→  }
   379→
   380→  for (const slug of specBySlug.keys()) {
   381→    visit(slug);
   382→  }
   383→
   384→  return { sorted, error: null };
   385→}
   386→
   387→/**
   388→ * Simple slugification helper
   389→ */
   390→function slugify(title: string): string {
   391→  return title
   392→    .toLowerCase()
   393→    .replace(/[^a-z0-9]+/g, "-")
   394→    .replace(/^-|-$/g, "");
   395→}
   396→
   397→/**
   398→ * Validate parent references.
   399→ *
   400→ * AC: @plan-import ac-17 - Detect missing parent references
   401→ * AC: @plan-import ac-33 - Provide recovery hints
   402→ *
   403→ * @param specs Specs to validate
   404→ * @param existingRefs Set of existing spec refs in the project
   405→ * @returns Errors for specs with invalid parents
   406→ */
   407→export function validateParentRefs(
   408→  specs: PlanSpec[],
   409→  existingRefs: Set<string>,
   410→): ParseError[] {
   411→  const errors: ParseError[] = [];
   412→  const planSlugs = new Set(
   413→    specs.map(s => s.slug || slugify(s.title))
   414→  );
   415→
   416→  for (const spec of specs) {
   417→    if (!spec.parent) continue;
   418→
   419→    const parentRef = spec.parent.startsWith("@") ? spec.parent.slice(1) : spec.parent;
   420→
   421→    // Check if parent exists in plan or project
   422→    if (!planSlugs.has(parentRef) && !existingRefs.has(parentRef)) {
   423→      errors.push({
   424→        type: "dependency",
   425→        message: `Parent ${spec.parent} not found. Check parent exists or define it earlier in plan`,
   426→        spec,
   427→      });
   428→    }
   429→  }
   430→
   431→  return errors;
   432→}
   433→
