   418→
   419→    const parentRef = spec.parent.startsWith("@") ? spec.parent.slice(1) : spec.parent;
   420→
   421→    // Check if parent exists in plan or project
   422→    if (!planSlugs.has(parentRef) && !existingRefs.has(parentRef)) {
   423→      errors.push({
   424→        type: "dependency",
   425→        message: `Parent ${spec.parent} not found. Check parent exists or define it earlier in plan`,
   426→        spec,
   427→      });
   428→    }
   429→  }
   430→
   431→  return errors;
   432→}
   433→
```

