          });
          return;
        }

        await saveTask(ctx, updatedTask);
        await commitIfShadow(
          ctx.shadow,
          "task-patch",
          foundTask.slugs[0] || index.shortUlid(foundTask._ulid),
          changes.join(", "),
        );
        success(
          `Patched task: ${index.shortUlid(updatedTask._ulid)} (${changes.join(", ")})`,
          { task: updatedTask },
