   153→  try {
   154→    execSync("git rev-parse --git-dir", {
   155→      cwd: dir,
   156→      stdio: ["pipe", "pipe", "pipe"],
   157→      encoding: "utf-8",
   158→    });
   159→    return true;
   160→  } catch {
