  8→import { type ChildProcess, spawn } from "node:child_process";
  9→import { ACPClient, type ACPClientOptions } from "../acp/index.js";
 10→import type { AgentAdapter } from "./adapters.js";
 11→
 12→/**
 13→ * Options for spawning an agent.
 14→ */
 15→export interface SpawnAgentOptions {
 16→  /** Working directory for the agent */
 17→  cwd: string;
 18→  /** Additional environment variables */
 19→  env?: Record<string, string>;
 20→  /** ACP client options */
 21→  clientOptions?: Omit<ACPClientOptions, "stdin" | "stdout">;
 22→}
 23→
 24→/**
 25→ * Result of spawning an agent.
 26→ */
 27→export interface SpawnedAgent {
 28→  /** The ACP client for communication */
 29→  client: ACPClient;
 30→  /** The child process handle */
 31→  process: ChildProcess;
 32→  /** Kill the agent process */
 33→  kill: (signal?: NodeJS.Signals) => void;
 34→}
 35→
 36→/**
 37→ * Spawn an ACP agent using the specified adapter.
 38→ *
 39→ * Creates a child process and wraps its stdio with an ACPClient.
 40→ * The caller is responsible for calling client.initialize() after spawning.
 41→ *
 42→ * @param adapter - Adapter definition specifying how to spawn the agent
 43→ * @param options - Spawn options including cwd and environment
 44→ * @returns SpawnedAgent with client, process, and kill function
 45→ */
 46→export function spawnAgent(
 47→  adapter: AgentAdapter,
 48→  options: SpawnAgentOptions,
 49→): SpawnedAgent {
 50→  const { cwd, env = {}, clientOptions = {} } = options;
 51→
 52→  // Merge environment variables
 53→  const processEnv = {
 54→    ...process.env,
 55→    ...adapter.env,
 56→    ...env,
 57→  };
 58→
 59→  // Spawn the agent process
 60→  const child = spawn(adapter.command, adapter.args, {
 61→    cwd,
 62→    env: processEnv,
 63→    shell: adapter.shell,
 64→    stdio: ["pipe", "pipe", "inherit"], // pipe stdin/stdout, inherit stderr
 65→  });
 66→
 67→  // Ensure stdin/stdout are available
 68→  if (!child.stdin || !child.stdout) {
 69→    child.kill();
 70→    throw new Error("Failed to create pipes for agent process");
 71→  }
 72→
 73→  // Create ACP client connected to child's stdio
 74→  // Note: From the client's perspective:
 75→  // - stdin is where we READ from (child's stdout)
 76→  // - stdout is where we WRITE to (child's stdin)
 77→  const client = new ACPClient({
 78→    ...clientOptions,
 79→    stdin: child.stdout, // We read from child's stdout
 80→    stdout: child.stdin as NodeJS.WritableStream, // We write to child's stdin
 81→  });
 82→
 83→  // Forward process exit to client close
 84→  child.on("exit", () => {
 85→    if (!client.isClosed()) {
 86→      client.close();
 87→    }
 88→  });
 89→
 90→  // Kill function with graceful shutdown
 91→  const kill = (signal: NodeJS.Signals = "SIGTERM"): void => {
 92→    if (!child.killed) {
 93→      child.kill(signal);
 94→    }
 95→  };
 96→
 97→  return { client, process: child, kill };
 98→}
 99→
100→/**
101→ * Spawn and initialize an ACP agent.
102→ *
103→ * Convenience function that spawns an agent and calls initialize().
104→ *
105→ * @param adapter - Adapter definition
106→ * @param options - Spawn options
107→ * @returns Initialized SpawnedAgent
108→ */
109→export async function spawnAndInitialize(
110→  adapter: AgentAdapter,
111→  options: SpawnAgentOptions,
112→): Promise<SpawnedAgent> {
113→  const agent = spawnAgent(adapter, options);
114→
115→  try {
116→    await agent.client.initialize();
117→    return agent;
118→  } catch (err) {
119→    // Clean up on initialization failure
120→    agent.kill();
121→    throw err;
122→  }
123→}
