import { createPrefixedRenderer } from '../src/ralph/cli-renderer.js';

describe('subagent module', () => {
  // AC: @ralph-subagent-spawning ac-2, ac-10
  describe('buildSubagentPrompt', () => {
    it('includes task reference in prompt', () => {
