  describe('--tasks flag (explicit task scope)', () => {
    let tempDir: string;

    beforeEach(async () => {
      tempDir = await setupTempFixtures();
    });

    afterEach(async () => {
      await cleanupTempDir(tempDir);
    });

    // AC: @cli-ralph ac-21 - Basic explicit task scope
    it('accepts --tasks flag with task references', async () => {
